// Mechanism-only tests; process substitutes do not qualify a native sandbox.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
const {engineeringEngineManifest,compileEngineeringPolicy,EngineeringEngineRuntime,verifyObservedEngineeringRules}=await import(new URL('../../packages/harness/lib/team-engine-runtime.js',import.meta.url).href) as typeof import('../../packages/harness/lib/types/team-engine-runtime.js');
const digest=(value:unknown)=>createHash('sha256').update(JSON.stringify(value)).digest('hex');
const policy=()=>{const p={policyId:'trusted-fixture',approvedOrigins:['https://github.com'],resolvedTuples:[{family:4 as const,address:'140.82.112.4',protocol:'tcp' as const,port:443}],deniedPrivateTuples:[{family:4 as const,address:'127.0.0.1',protocol:'tcp' as const,port:443}],resolvedAt:new Date(Date.now()-1000).toISOString(),validUntil:new Date(Date.now()+30000).toISOString()};return {...p,sha256:digest(p)};};
test('trusted namespace compiler defaults IPv4/IPv6 to drop and only admits bounded HTTPS tuples',()=>{const p=policy();const result=compileEngineeringPolicy(p);assert.match(result.bytes,/table inet hima/);assert.match(result.bytes,/policy drop/);assert.match(result.bytes,/set allow4.*ipv4_addr \. inet_service/);assert.match(result.bytes,/set allow6.*ipv6_addr \. inet_service/);assert.match(result.bytes,/flags timeout/);assert.match(result.bytes,/140\.82\.112\.4 \. 443 timeout \d+s/);assert.match(result.bytes,/ip daddr \. tcp dport @allow4 meta time < \d+ accept/);assert.match(result.bytes,/ip6 daddr \. tcp dport @allow6 meta time < \d+ accept/);assert.doesNotMatch(result.bytes,/ct state.*accept|udp|[dt]port 53\b/);assert.equal(result.policySha256,p.sha256);});
test('expired, modified, private-colliding or arbitrary-port policy is refused before bootstrap',()=>{for(const kind of ['expired','hash','private','port','origin']) {const p=policy();if(kind==='expired')p.validUntil=new Date(0).toISOString();if(kind==='hash')p.sha256='0'.repeat(64);if(kind==='private')p.resolvedTuples[0]!.address='127.0.0.1';if(kind==='port')p.resolvedTuples[0]!.port=80;if(kind==='origin')p.approvedOrigins=['http://github.com'];if(kind!=='hash'){const {sha256:_,...body}=p;p.sha256=digest(body);}assert.throws(()=>compileEngineeringPolicy(p),/policy|HTTPS|private|expired|origin/i,kind);}});
test('engine metadata is strict, target-specific and forbids member qualification',()=>{assert.equal(engineeringEngineManifest.safeParse({kind:'podman',provider:'applehv',version:'6.1.3',arbitraryArgv:[]}).success,false);});


