 const f=await macC7Fixture();try{const started=await f.runtime.start('engineering-engine');assert.equal(started.state,'running',started.diagnostic?.message);const admitted=started.owned.engine!.connectionSha256;const startLog=await f.log();const firstControl=startLog.findIndex(a=>a[0]==='--connection');assert.ok(firstControl>0);await f.runtime.prepareNamespace({engineGeneration:started.generation,taskIdentity:{taskId:'trusted',fixture:'trusted-namespace-test'},policy:f.p});await f.rebind(started);const before=(await f.log()).length;const result=await f.runtime[operation]('engineering-engine');assert.equal(result.state,'failed');assert.equal(result.owned.quiescent,false);assert.equal(result.owned.engine!.connectionSha256,admitted);const after=(await f.log()).slice(before);assert.ok(!after.some(a=>a[0]==='--connection'||a[0]==='machine'&&a[1]==='ssh'),'drift must issue no named image/container or guest SSH commands');assert.match(result.diagnostic!.message,/connection/i);assert.ok(startLog.slice(0,firstControl).some(a=>a[0]==='system'&&a[1]==='connection'),'initial private connection must precede load/image control');}finally{await f.cleanup();}
