for(const mode of ['clock-nan','clock-negative','clock-skew','clock-reverse','clock-slow','clock-uncertain','install-late','install-clock-backward','install-mono-backward','install-zero','install-ttl-too-long','install-nan','install-host-delay','permanent-observation','missing-guard'])test(`public C7 refuses ${mode} without a readiness lease and reconciles its owned bootstrap`,{skip:process.platform!=='darwin'?'Mac-shaped process seam':false},async()=>{const f=await macC7Fixture(mode);try{const started=await f.runtime.start('engineering-engine');assert.equal(started.state,'running',started.diagnostic?.message);await assert.rejects(f.runtime.prepareNamespace({engineGeneration:started.generation,taskIdentity:{taskId:'trusted',fixture:'trusted-namespace-test'},policy:f.p}),mode.startsWith('clock-')?/clock/i:mode.includes('observation')||mode==='missing-guard'?/Observed/:/installation/);const failed=await f.runtime.status('engineering-engine');assert.equal(failed.state,'failed');assert.equal(failed.owned.engine!.namespaces.length,0,'failed admission must reconcile the exact bootstrap before returning');assert.ok(!f.receipts.some(r=>r.owned.engine?.namespaces.some(n=>!!n.observedRulesSha256)),'no readiness receipt may survive failed admission');const stopped=await f.runtime.stop('engineering-engine');assert.equal(stopped.state,'stopped',stopped.diagnostic?.message);assert.equal(stopped.owned.quiescent,true);}finally{await f.cleanup();}});

for(const control of ['stop','expiry'] as const)test(`public C7 gated receipt refuses a live lease after ${control} while preserving its historical capture`,{skip:process.platform!=='darwin'?'Mac-shaped process seam':false},async t=>{let release!:()=>void,notice!:(r:TeamServiceReceipt)=>void;const gate=new Promise<void>(resolve=>{release=resolve;}),captured=new Promise<TeamServiceReceipt>(resolve=>{notice=resolve;});const f=await macC7Fixture('valid',async r=>{if(r.operation==='status'&&r.state==='running'&&r.owned.engine?.namespaces.some(n=>!!n.observedRulesSha256)){notice(r);await gate;}});try{const started=await f.runtime.start('engineering-engine');assert.equal(started.state,'running',started.diagnostic?.message);const preparing=f.runtime.prepareNamespace({engineGeneration:started.generation,taskIdentity:{taskId:'receipt-gate',fixture:'trusted-namespace-test'},policy:f.p});const outcome=preparing.then(lease=>({lease,error:undefined}),error=>({lease:undefined,error}));const historical=await captured,value=JSON.stringify(historical),hash=digest(historical);let stopped:Promise<TeamServiceReceipt>|undefined;if(control==='stop')stopped=f.runtime.stop('engineering-engine');else t.mock.method(Date,'now',()=>Date.parse(f.p.validUntil)+1);release();const result=await outcome;t.mock.restoreAll();assert.equal(result.lease,undefined,'persistence may retain a past running capture but cannot hand out a revoked/expired live lease');assert.match(String(result.error),/fenced|expired|readiness|handoff/i);assert.equal(JSON.stringify(historical),value);assert.equal(digest(historical),hash);assert.equal(f.persisted.get(historical.receiptId),value);const closed=await (stopped??f.runtime.stop('engineering-engine'));assert.equal(closed.state,'stopped',closed.diagnostic?.message);assert.equal(closed.owned.quiescent,true);}finally{release();t.mock.restoreAll();await f.cleanup();}});

