 const {execFile}=await import('node:child_process');const {promisify}=await import('node:util');const root=await realpath(await mkdtemp(path.join(os.tmpdir(),'c7-cli-timeout-'))),home=path.join(root,'home'),assets=path.join(root,'assets');await mkdir(home);await mkdir(assets);const identityFields='pid=,ppid=,pgid=,'+(process.platform==='linux'?'sid=':'sess=')+',lstart=,args=';const effect=path.join(assets,'effect.mjs'),record=path.join(root,'effect.json'),parentRecord=path.join(root,'parent.json');
