 const receipts:TeamServiceReceipt[]=[];const engine=new EngineeringEngineRuntime({home,runtimeDirectory:assets,readManifest:async()=>({engineeringEngine:metadata,files}),recordReceipt:async r=>{receipts.push(r);}});const actualSetTimeout=globalThis.setTimeout;let deadlineFired=false,declaredDeadline=0,settled=false;let advanceDeadline:(()=>void)|undefined;
